INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15779$nota-0258$m15779$, $m15780$Exercise Physiology McArdle.pdf$m15780$, $m15781$630$m15781$, $m15782$A progressive slowing of marathon running performance of men and women as the wet bulb–globe temperature (WB-GT) increased from 10 to 25°C (50 to 77°F) with performance more negatively affected for slower runners. (Adapted with permission from Ely MR, et al. Impact of weather on marathon-running performance. Med Sci Sports Exerc 2007;39:487.)$m15782$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15783$nota-0258$m15783$, $m15784$nota-0252$m15784$, $m15785$complementa$m15785$, $m15786$nota-0252 traz os limiares de risco por WBGT; esta nota traz o efeito gradual (não binário) de degradação de desempenho conforme a temperatura sobe dentro e além dessas faixas$m15786$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15787$nota-0258$m15787$, $m15788$nota-0254$m15788$, $m15789$complementa$m15789$, $m15790$citada no corpo da nota como explicação de por que atletas mais condicionados/aclimatizados toleram melhor o calor que atletas mais lentos — link estrutural ausente até auditoria de 2026-08-02$m15790$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15791$nota-0261$m15791$, $m15792$Exercise Physiology McArdle.pdf$m15792$, $m15793$636$m15793$, $m15794$Heat cramps—severe involuntary, sustained, and spreading muscle spasms—occur during or after intense physical activity... Core temperature often remains within normal range. Crampers tend to have high sweat rates and/or high sweat sodium concentrations.$m15794$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15795$nota-0261$m15795$, $m15796$Exercise Physiology McArdle.pdf$m15796$, $m15797$636$m15797$, $m15798$Heat exhaustion can develop in unacclimatized persons during the first summer heat wave or with the first hard training session on a hot day... Characteristics of heat exhaustion include a weak and rapid pulse, low blood pressure in the upright position, headache, dizziness, and general weakness... core temperature does not rise to dangerous levels of 40°C (104°F) or higher.$m15798$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15799$nota-0261$m15799$, $m15800$Exercise Physiology McArdle.pdf$m15800$, $m15801$636$m15801$, $m15802$The classic form of heat stroke—core temperature exceeds 40.5°C (105°F), altered mental status, absence of sweating—usually occurs during heat waves... Exertional heat stroke is a state of extreme hyperthermia... body temperature rises to 41.5°C (106.7°F) and above.$m15802$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15803$nota-0261$m15803$, $m15804$nota-0253$m15804$, $m15805$complementa$m15805$, $m15806$nota-0253 traz o índice de triagem ambiental que precede e contextualiza o risco destes quadros clínicos$m15806$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15807$nota-0261$m15807$, $m15808$nota-0254$m15808$, $m15809$complementa$m15809$, $m15810$atletas não aclimatados (nota-0254) apresentam maior risco de exaustão por calor, especialmente na primeira sessão intensa em dia quente$m15810$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15811$nota-0261$m15811$, $m15812$nota-0262$m15812$, $m15813$complementa$m15813$, $m15814$obesidade/sobrepeso (nota-0262) é fator predisponente citado no corpo da nota — nota-0262 já cita nota-0261 de volta; link estrutural nesta direção estava ausente até auditoria de 2026-08-02$m15814$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15815$nota-0262$m15815$, $m15816$Exercise Physiology McArdle.pdf$m15816$, $m15817$634$m15817$, $m15818$Excess body fat and body weight directly adds to the metabolic cost of weight-bearing activities. A hot, humid environment places the overly fat person at a distinct disadvantage for temperature regulation and physical performance. Additional compounding factors include the added weight of sports equipment... Fatal heat stroke occurs 3.5 times more frequently in excessively overweight young adults than in individuals of average body size.$m15818$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15819$nota-0262$m15819$, $m15820$nota-0261$m15820$, $m15821$complementa$m15821$, $m15822$gordura corporal excessiva é um dos fatores predisponentes ao golpe de calor descrito na nota-0261$m15822$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15823$nota-0263$m15823$, $m15824$Exercise Physiology McArdle.pdf$m15824$, $m15825$625$m15825$, $m15826$For cyclists, wearing a commercially available helmet provides vital protection against possible head trauma, but does the cycling helmet impede thermoregulatory processes in a hot–dry or hot–humid environment?... 10 male and 4 female competitive cyclists pedaled for 90 min at 60% of VO2peak in both hot–dry (35°C [95°F], 20% relative humidity) and hot–humid (35°C [95°F], 70% relative humidity) environments, with and without a protective helmet.$m15826$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15827$nota-0263$m15827$, $m15828$Exercise Physiology McArdle.pdf$m15828$, $m15829$626$m15829$, $m15830$Wearing the helmet, however, did not increase the riders' heat strain or perceived heat sensation from the head or body.$m15830$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15831$nota-0265$m15831$, $m15832$Exercise Physiology McArdle.pdf$m15832$, $m15833$634$m15833$, $m15834$Research shows little or no age-related decrements in thermoregulatory capacity or heat-stress acclimatization with appropriate controls for body size and composition, aerobic fitness, hydration, degree of acclimatization, and chronological age.$m15834$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15835$nota-0265$m15835$, $m15836$Exercise Physiology McArdle.pdf$m15836$, $m15837$635$m15837$, $m15838$In essence, women tolerate the thermal stress of physical activity at least as well as do men of comparable aerobic fitness and level of acclimatization; both genders also acclimatize to the same degree... Women probably use circulatory mechanisms for heat dissipation, whereas men make greater use of evaporative cooling.$m15838$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15839$nota-0265$m15839$, $m15840$nota-0254$m15840$, $m15841$complementa$m15841$, $m15842$esta nota detalha como idade e gênero modulam a resposta de aclimatização ao calor descrita na nota-0254$m15842$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15843$nota-0266$m15843$, $m15844$Exercise Physiology McArdle.pdf$m15844$, $m15845$641$m15845$, $m15846$Wind Chill (ºF) = 35.74 + 0.6215 T - 35.75 (V0.16) + 0.4275 T (V0.16), Where, T = Air Temperature (ºF); V = Wind Speed (mph)... Frostbite Times: 30 minutes, 10 minutes, 5 minutes.$m15846$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15847$nota-0266$m15847$, $m15848$Exercise Physiology McArdle.pdf$m15848$, $m15849$640$m15849$, $m15850$If a person runs, skis, or skates into the wind, the effective cooling increases directly with forward velocity. Running at 8 mph into a 12-mph headwind creates the equivalent of a 20-mph wind speed. Conversely, running at 8 mph with a 12-mph wind at one's back creates a relative wind speed of only 4 mph.$m15850$);
